files.content:
body {
  background: #fff4e6;
  color: #5a3e2b;
  font-family: Georgia, serif;
  margin: 0;
  padding: 20px;
}

header {
  text-align: center;
}

.avatar {
  font-size: 64px;
  margin: 0;
}

h1 {
  color: #d9534f;
  font-size: 40px;
}

h2 {
  color: #e07b39;
}

section {
  background: #ffffff;
  border: 2px solid #f4c095;
  border-radius: 16px;
  padding: 20px;
  margin: 20px auto;
  max-width: 500px;
}

li {
  font-size: 18px;
  margin: 8px 0;
}

footer {
  text-align: center;
  font-size: 14px;
}

